{
  "id": 1,
  "jsonrpc": "2.0",
  "result": {
    "tools": [
      {
        "description": "Ask for approval of a tool call that needs a permission prompt.",
        "inputSchema": {
          "properties": {
            "input": {
              "type": "object"
            },
            "tool_name": {
              "type": "string"
            },
            "tool_use_id": {
              "type": "string"
            }
          },
          "required": [
            "tool_name",
            "input"
          ],
          "type": "object"
        },
        "name": "approve"
      },
      {
        "description": "Ask the owner for a folder, file or website your sandbox blocks (a command failed with \"Operation not permitted\", or the network was refused). Give the absolute path, or the host name, and why. The answer comes at your next turn: after this call, end your turn and say what you are waiting for.",
        "inputSchema": {
          "properties": {
            "domain": {
              "description": "host name, e.g. pypi.org",
              "type": "string"
            },
            "path": {
              "description": "absolute path of the file or folder",
              "type": "string"
            },
            "reason": {
              "type": "string"
            },
            "write": {
              "description": "also write there (default: read only)",
              "type": "boolean"
            }
          },
          "required": [
            "reason"
          ],
          "type": "object"
        },
        "name": "request_access"
      },
      {
        "description": "Report a bug in Kith itself (not in the person's own work). Give a short title and what happened. It is scrubbed of secrets and personal details, shown to the owner on a card, and filed on GitHub only if they say yes. Tell the person what you reported and that it waits on the owner.",
        "inputSchema": {
          "properties": {
            "details": {
              "description": "what happened, what you expected",
              "type": "string"
            },
            "title": {
              "type": "string"
            }
          },
          "required": [
            "title"
          ],
          "type": "object"
        },
        "name": "report_bug"
      },
      {
        "description": "Ask the owner for a key or token of a service you need (one the service declares) and are not allowed to use yet. The owner picks an existing account or types the key into a card; you never see it. The answer comes at your next turn: after this call, end your turn and say what you are waiting for.",
        "inputSchema": {
          "properties": {
            "purpose": {
              "description": "what you need it for",
              "type": "string"
            },
            "service": {
              "description": "service name, e.g. github",
              "type": "string"
            }
          },
          "required": [
            "service",
            "purpose"
          ],
          "type": "object"
        },
        "name": "request_secret"
      },
      {
        "description": "Put one card on the owner's Feed: something they would want to look at (a result, a number that moved, a page or video you made, a link). One line of what and why, not a log. Give at most one of file, url or number. `fold` names a card of yours that this replaces (a later post with the same fold updates it instead of adding another); you may start a few new cards a day. Use kind `merges` with `pr` for a PR you merged.",
        "inputSchema": {
          "properties": {
            "file": {
              "description": "path of a file to show (.html makes a page, .mp4/.mov a video), up to 100 MiB",
              "type": "string"
            },
            "fold": {
              "description": "a-z, 0-9 and -, at most 40: posts with the same fold are one card",
              "type": "string"
            },
            "kind": {
              "description": "a short word: file, number, page, video, link, failing, ...",
              "type": "string"
            },
            "line": {
              "description": "one more line, at most 200 characters",
              "type": "string"
            },
            "number": {
              "description": "a figure: value, unit?, delta? (the change)",
              "properties": {
                "delta": {
                  "type": "number"
                },
                "unit": {
                  "type": "string"
                },
                "value": {
                  "type": "number"
                }
              },
              "required": [
                "value"
              ],
              "type": "object"
            },
            "pr": {
              "description": "owner/repo#number, with kind merges",
              "type": "string"
            },
            "title": {
              "description": "one line, at most 80 characters",
              "type": "string"
            },
            "url": {
              "description": "an https link",
              "type": "string"
            }
          },
          "required": [
            "kind",
            "title"
          ],
          "type": "object"
        },
        "name": "feed_post"
      }
    ]
  }
}
